# compare
for bp, ap in zip(sorted(baseline['projects'], key=lambda p: p['path']), sorted(after['projects'], key=lambda p: p['path'])):
    bpkgs = {p['id']: p['resolvedVersion'] for f in bp['frameworks'] for p in f['topLevelPackages']}
    apkgs = {p['id']: p['resolvedVersion'] for f in ap['frameworks'] for p in f['topLevelPackages']}
    if bpkgs != apkgs:
        print(f'DIFF in {bp[\"path\"]}: {bpkgs} vs {apkgs}')
print('All packages match baseline.' if all(
    {p['id']: p['resolvedVersion'] for f in bp['frameworks'] for p in f['topLevelPackages']} ==
    {p['id']: p['resolvedVersion'] for f in ap['frameworks'] for p in f['topLevelPackages']}
    for bp, ap in zip(sorted(baseline['projects'], key=lambda p: p['path']), sorted(after['projects'], key=lambda p: p['path']))
) else 'DIFFERENCES FOUND')
"

